interface Entry<T> { value: T; expires: number; }
export class TTLCache<T> { private readonly values = new Map<string, Entry<T>>(); constructor(private readonly ttlMs = 300_000, private readonly max = 1000) {} get(key: string): T | undefined { const entry = this.values.get(key); if (!entry) return undefined; if (entry.expires < Date.now()) { this.values.delete(key); return undefined; } return entry.value; } set(key: string, value: T, ttlMs = this.ttlMs): void { if (this.values.size >= this.max && !this.values.has(key)) this.values.delete(this.values.keys().next().value as string); this.values.set(key, { value, expires: Date.now() + ttlMs }); } delete(key: string) { this.values.delete(key); } clear() { this.values.clear(); } }
export const cache = new TTLCache<unknown>();
